#!/usr/bin/env node
import { readdirSync, readFileSync, writeFileSync, mkdirSync, existsSync, unlinkSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const ENABLED_PATH = join(ROOT, 'scripts/bazel/enabled-packages.json');
const HEADER = [
  '# Generated by scripts/bazel/generate-package-build.mjs — do not edit by hand.',
  '# Re-run: node scripts/bazel/generate-package-build.mjs',
  '',
].join('\n');

function loadJson(path) {
  return JSON.parse(readFileSync(path, 'utf8'));
}

function packageKind(dirName, pkg) {
  if (dirName.startsWith('npm-') || String(pkg.name || '').startsWith('@neko-catpital-labs/')) {
    return 'npm-wrapper';
  }
  if (dirName === 'app') return 'electron';
  if (dirName === 'ui' || dirName === 'web-app') return 'vite';
  const build = String(pkg.scripts?.build ?? '');
  if (build.includes('vite') && !build.includes('tsup')) return 'vite';
  if (build.includes('tsup') || build.includes('vite')) return 'tsup';
  if (String(pkg.scripts?.test ?? '').startsWith('echo')) return 'noop-test';
  return 'other';
}

function renderPackageBuild(dirName, pkg) {
  const name = pkg.name;
  const kind = packageKind(dirName, pkg);
  const hasTest = Boolean(pkg.scripts?.test) && !String(pkg.scripts.test).startsWith('echo');
  const hasBuild = Boolean(pkg.scripts?.build);
  const tags = ['no-sandbox', 'local', `kind_${kind}`];
  if (kind === 'electron' || kind === 'vite') {
    tags.push('no-remote-exec');
  }
  const tagLit = tags.map((t) => `"${t}"`).join(', ');
  const lines = [HEADER, 'exports_files(["package.json"])', ''];
  if (hasBuild) {
    lines.push(
      'sh_binary(',
      '    name = "build",',
      '    srcs = ["//scripts/bazel:run_pnpm_filter.sh"],',
      `    args = ["${name}", "build"],`,
      `    tags = [${tagLit}],`,
      ')',
      '',
    );
  }
  if (hasTest) {
    lines.push(
      'sh_test(',
      '    name = "test",',
      '    srcs = ["//scripts/bazel:run_pnpm_filter.sh"],',
      `    args = ["${name}", "test"],`,
      '    size = "medium",',
      `    tags = [${tagLit}],`,
      ')',
      '',
    );
  }
  return lines.join('\n');
}

function renderScriptsBazelBuild() {
  return [
    HEADER,
    'exports_files([',
    '    "run_pnpm_filter.sh",',
    '    "run_workspace_cmd.sh",',
    '])',
    '',
  ].join('\n');
}

function renderRootBuild(enabled) {
  const lines = [HEADER, ''];
  if (enabled.quality) {
    for (const [name, ...cmd] of [
      ['check_types', 'pnpm', 'run', 'check:types'],
      ['check_deps', 'pnpm', 'run', 'check:deps'],
      ['check_comments', 'pnpm', 'run', 'check:comments'],
    ]) {
      lines.push(
        'sh_test(',
        `    name = "${name}",`,
        '    srcs = ["//scripts/bazel:run_workspace_cmd.sh"],',
        `    args = [${cmd.map((c) => `"${c}"`).join(', ')}],`,
        '    size = "large",',
        '    tags = ["no-sandbox", "local", "quality"],',
        ')',
        '',
      );
    }
  }
  if (enabled.playwright) {
    lines.push(
      'sh_test(',
      '    name = "playwright_e2e",',
      '    srcs = ["//scripts/bazel:run_pnpm_filter.sh"],',
      '    args = ["@invoker/app", "test:e2e"],',
      '    size = "enormous",',
      '    tags = ["no-sandbox", "local", "no-remote-exec", "playwright"],',
      ')',
      '',
    );
  }
  if (enabled.packaging) {
    lines.push(
      'sh_binary(',
      '    name = "dist_cli",',
      '    srcs = ["//scripts/bazel:run_workspace_cmd.sh"],',
      '    args = ["pnpm", "run", "dist:cli"],',
      '    tags = ["no-sandbox", "local", "packaging"],',
      ')',
      '',
      'sh_binary(',
      '    name = "dist_desktop_linux",',
      '    srcs = ["//scripts/bazel:run_workspace_cmd.sh"],',
      '    args = ["bash", "scripts/package-desktop.sh", "--linux"],',
      '    tags = ["no-sandbox", "local", "packaging"],',
      ')',
      '',
    );
  }
  return lines.join('\n');
}

function writeBazelIgnore(packagesRoot) {
  const lines = [
    'node_modules',
    '.git',
    '.invoker',
    'coverage',
    'release',
    'local-builds',
    'tmp',
    'docker/agent-base',
  ];
  for (const dirName of readdirSync(packagesRoot)) {
    if (!existsSync(join(packagesRoot, dirName, 'package.json'))) continue;
    lines.push(`packages/${dirName}/node_modules`);
  }
  lines.push('');
  writeFileSync(join(ROOT, '.bazelignore'), lines.join('\n'));
}

const enabled = loadJson(ENABLED_PATH);
const packageDirs = new Set(enabled.packages ?? []);
mkdirSync(join(ROOT, 'scripts/bazel'), { recursive: true });
writeFileSync(join(ROOT, 'scripts/bazel/BUILD.bazel'), renderScriptsBazelBuild());

const packagesRoot = join(ROOT, 'packages');
for (const dirName of readdirSync(packagesRoot)) {
  const pkgPath = join(packagesRoot, dirName, 'package.json');
  if (!existsSync(pkgPath)) continue;
  const buildPath = join(packagesRoot, dirName, 'BUILD.bazel');
  if (!packageDirs.has(dirName)) {
    if (existsSync(buildPath)) {
      const existing = readFileSync(buildPath, 'utf8');
      if (existing.startsWith('# Generated by scripts/bazel/generate-package-build.mjs')) {
        unlinkSync(buildPath);
      }
    }
    continue;
  }
  writeFileSync(buildPath, renderPackageBuild(dirName, loadJson(pkgPath)));
}

writeFileSync(join(ROOT, 'BUILD.bazel'), renderRootBuild(enabled));
writeBazelIgnore(packagesRoot);
console.log(
  `Generated BUILD.bazel for ${packageDirs.size} package(s); quality=${Boolean(enabled.quality)} playwright=${Boolean(enabled.playwright)} packaging=${Boolean(enabled.packaging)}`,
);
